function img(id: string): string {
  return `https://images.unsplash.com/${id}?w=1600&q=80&auto=format&fit=crop`;
}

function pics(pool: string[]): string[] {
  return pool.map(img);
}

/**
 * Varijanta kadra iste fotografije.
 *
 * Biblioteka ima 51 provjerenu sliku, a oglasa je 1151 — dijeljenje je neizbježno.
 * Skupine su barem segmentno točne (hatchback→hatchback, SUV→SUV), ali dvadeset
 * oglasa s PIKSEL-IDENTIČNOM naslovnicom izgleda kao greška. Zato isti ID dobiva
 * različit izrez/zoom po oglasu: Unsplash radi obradu na CDN-u, pa je rezultat
 * vizualno drukčiji kadar bez dodatnih datoteka i bez novog mrežnog troška.
 *
 * `n` je indeks oglasa (deterministički) → isti oglas uvijek ima isti kadar.
 */
const CROPS = ["entropy", "edges", "center", "faces"] as const;
function varyCrops(urls: string[], n: number): string[] {
  return urls.map((url, i) => {
    const id = url.split("/").pop()?.split("?")[0];
    if (!id) return url;
    const crop = CROPS[(n + i) % CROPS.length];
    const zoom = 1 + ((n + i * 3) % 4) * 0.06; // 1.00 – 1.18
    const w = Math.round(1600 * zoom);
    return `https://images.unsplash.com/${id}?w=${w}&q=80&auto=format&fit=crop&crop=${crop}`;
  });
}

