let counter = 0;

function buildListing(spec: Spec): Listing {
  counter++;
  const id = `lst-${String(counter).padStart(4, "0")}`;
  const titleParts = [spec.make, spec.model, spec.variant].filter(Boolean);
  const title = `${titleParts.join(" ")} · ${spec.year}.`;
  const slug = `${slugify(`${spec.make}-${spec.model}-${spec.variant ?? ""}-${spec.year}-${spec.city}`)}-${id}`;
  const createdAt = new Date(Date.now() - spec.daysAgo * 24 * 60 * 60 * 1000).toISOString();

  // Deterministic demo enrichment (every 5th listing is on sale, every 3rd has full history)
  const onSale = counter % 5 === 0;
  const hasHistory = counter % 3 === 0;
  const isImport = counter % 7 === 0;
  const originalPriceEur = onSale ? Math.round((spec.priceEur * (1 + (8 + (counter % 8)) / 100)) / 100) * 100 : undefined;
  const accidentHistory = hasHistory
    ? counter % 9 === 0
      ? "Lakša šteta popravljena u ovlaštenom servisu"
      : "Bez nesreće"
    : undefined;
  const serviceHistory = hasHistory ? "Potpuna servisna knjižica" : undefined;
  const importedFrom = isImport ? "Njemačka" : undefined;
  const vinMasked = hasHistory ? `WVW***********${String(counter).padStart(4, "0")}` : undefined;

  return {
    id,
    slug,
    title,
    category: spec.category ?? "auto",
    // Karlo 31.07: "Osobni auto" (`auto-oglasi`) je sad prava podkategorija.
    // Auto oglas bez podkategorije JEST osobni automobil — bez ovoga bi rubrika
    // bila prazna, a 52 oglasa dostupna samo preko "Auto" bez filtera.
    subcategory:
      spec.subcategory ?? ((spec.category ?? "auto") === "auto" ? "auto-oglasi" : undefined),
    attributes: spec.attributes,
    make: spec.make,
    model: spec.model,
    variant: spec.variant,
    year: spec.year,
    priceEur: spec.priceEur,
    originalPriceEur,
    km: spec.km,
    fuel: spec.fuel,
    transmission: spec.transmission,
    bodyType: spec.bodyType,
    drive: spec.drive,
    color: spec.color,
    condition: spec.condition ?? (spec.km < 5000 ? "Novo" : "Rabljeno"),
    engineCc: spec.engineCc,
    powerKw: spec.powerKw,
    doors: spec.doors ?? (spec.bodyType === "Hatchback" || spec.bodyType === "Coupe" ? 5 : 5),
    seats: spec.seats ?? 5,
    vinMasked,
    accidentHistory,
    serviceHistory,
    importedFrom,
    city: spec.city,
    county: spec.county,
    description: spec.description,
    features: spec.features,
    // Varijanta kadra po oglasu — vidi picsVaried(). Radi na već izgrađenim
    // URL-ovima da ne treba mijenjati 1151 poziv pics() u nizovima specifikacija.
    images: varyCrops(spec.photos, counter),
    sellerName: spec.sellerName,
    sellerType: spec.sellerType,
    sellerPhone: spec.sellerPhone,
    views: spec.views ?? Math.floor(Math.random() * 850) + 80,
    phoneReveals: 0,
    featured: spec.featured ?? false,
    createdAt,
    registrationUntil: spec.registrationUntil,
    firstRegistered: `${String(Math.floor(Math.random() * 12) + 1).padStart(2, "0")}/${spec.year}`,
  };
}

export const LISTINGS: Listing[] = [...SPECS, ...EXTRA_SPECS, ...EXTRA2_SPECS].map(
  buildListing
);

export function getListing(slug: string): Listing | undefined {
  return LISTINGS.find((l) => l.slug === slug);
}

export function getListingsByMake(makeSlug: string): Listing[] {
  return LISTINGS.filter(
    (l) => slugify(l.make) === makeSlug
  );
}

export function getFeaturedListings(limit = 6): Listing[] {
  return LISTINGS.filter((l) => l.featured).slice(0, limit);
}

export function getRelatedListings(listing: Listing, limit = 4): Listing[] {
  return LISTINGS.filter(
    (l) => l.id !== listing.id && (l.make === listing.make || l.bodyType === listing.bodyType)
  ).slice(0, limit);
}
